<script setup lang="ts">import{computed}from"vue";import{programmesFor}from"@/domain/iptv/epgStore";import type{IptvChannelRecord}from"@/types/records";const props=defineProps<{channel:IptvChannelRecord}>();const id=computed(()=>props.channel.epg_id||props.channel.tvg_id||"");const programmes=computed(()=>id.value?programmesFor(id.value):[]);</script><template><section class="iptv-programme-guide" aria-labelledby="programme-guide-title"><h3 id="programme-guide-title">Programação</h3><p v-if="!id">Canal sem associação EPG.</p><p v-else-if="!programmes.length">Sem programação futura disponível.</p><ol v-else><li v-for="programme in programmes" :key="`${programme.channelId}-${programme.start}-${programme.title}`"><time :datetime="programme.start">{{new Date(programme.start).toLocaleString("pt-PT")}}</time><strong>{{programme.title}}</strong><p v-if="programme.description">{{programme.description}}</p></li></ol></section></template>
